import java.util.ArrayDeque;
import java.util.Deque;
import java.util.PriorityQueue;
import java.util.Queue;

public class StacksQueuesTour {
    record Patient(String name, int urgency, int arrival) {}

    public static void main(String[] args) {
        // Stack (LIFO): an editor's undo history
        Deque<String> undo = new ArrayDeque<>();
        for (String edit : new String[]{"type 'Hi'", "bold", "type ' there'"}) {
            undo.push(edit);
            System.out.println("do   " + edit + " (undo size " + undo.size() + ")");
        }
        System.out.println("undo " + undo.pop());
        System.out.println("undo " + undo.pop());
        System.out.println("next undo would be: " + undo.peek());

        // Queue (FIFO): print jobs are served in arrival order
        Queue<String> printer = new ArrayDeque<>();
        printer.offer("report.pdf");
        printer.offer("photo.png");
        printer.offer("notes.txt");
        StringBuilder order = new StringBuilder();
        while (!printer.isEmpty()) order.append(printer.poll()).append(printer.isEmpty() ? "" : " -> ");
        System.out.println("printed: " + order);

        // Priority queue: most urgent first, ties by arrival
        PriorityQueue<Patient> triage = new PriorityQueue<>(
                (a, b) -> a.urgency() != b.urgency() ? Integer.compare(b.urgency(), a.urgency())
                                                     : Integer.compare(a.arrival(), b.arrival()));
        String[] names = {"Ana", "Ben", "Cai", "Dev"};
        int[] urgency = {2, 5, 2, 4};
        for (int i = 0; i < names.length; i++) triage.offer(new Patient(names[i], urgency[i], i));
        System.out.print("treated:");
        while (!triage.isEmpty()) {
            Patient p = triage.poll();
            System.out.print(" " + p.name() + "(" + p.urgency() + ")");
        }
        System.out.println();
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class StackOperations {
    static class ArrayStack {
        private String[] items = new String[2];
        private int size = 0;

        void push(String item) {
            if (size == items.length) {
                items = Arrays.copyOf(items, items.length * 2);   // grow: O(n), but rare
                System.out.println("  (grew capacity to " + items.length + ")");
            }
            items[size++] = item;
        }

        String pop() {
            if (size == 0) throw new IllegalStateException("pop from empty stack");
            String top = items[--size];
            items[size] = null;                                   // let the GC reclaim it
            return top;
        }

        String peek() {
            if (size == 0) throw new IllegalStateException("peek at empty stack");
            return items[size - 1];
        }

        boolean isEmpty() { return size == 0; }

        String state() {
            return "bottom " + Arrays.toString(Arrays.copyOf(items, size)) + " top, capacity " + items.length;
        }
    }

    public static void main(String[] args) {
        ArrayStack stack = new ArrayStack();
        for (String page : new String[]{"home", "search", "results", "item"}) {
            stack.push(page);
            System.out.println("push " + page + ": " + stack.state());
        }
        System.out.println("peek -> " + stack.peek());
        while (!stack.isEmpty()) {
            String top = stack.pop();
            System.out.println("pop -> " + top + ": " + stack.state());
        }
        try {
            stack.pop();
        } catch (IllegalStateException e) {
            System.out.println("error: " + e.getMessage());
        }

        // The library stack: ArrayDeque, top = first element
        Deque<Integer> library = new ArrayDeque<>();
        library.push(1);
        library.push(2);
        library.push(3);
        System.out.println("ArrayDeque pop order: " + library.pop() + " " + library.pop() + " " + library.pop());
    }
}

