class ArrayStack:
    def __init__(self):
        self.items = [None] * 2
        self.size = 0

    def push(self, item):
        if self.size == len(self.items):
            self.items = self.items + [None] * len(self.items)  # grow: O(n), but rare
            print(f"  (grew capacity to {len(self.items)})")
        self.items[self.size] = item
        self.size += 1

    def pop(self):
        if self.size == 0:
            raise IndexError("pop from empty stack")
        self.size -= 1
        top = self.items[self.size]
        self.items[self.size] = None  # drop the reference
        return top

    def peek(self):
        if self.size == 0:
            raise IndexError("peek at empty stack")
        return self.items[self.size - 1]

    def is_empty(self):
        return self.size == 0

    def state(self):
        shown = ", ".join(self.items[:self.size])
        return f"bottom [{shown}] top, capacity {len(self.items)}"


stack = ArrayStack()
for page in ["home", "search", "results", "item"]:
    stack.push(page)
    print(f"push {page}: {stack.state()}")
print("peek ->", stack.peek())
while not stack.is_empty():
    top = stack.pop()
    print(f"pop -> {top}: {stack.state()}")
try:
    stack.pop()
except IndexError as e:
    print("error:", e)

