import java.util.Arrays;

public class QueueOperations {
    static class CircularQueue {
        private String[] items = new String[4];
        private int head = 0;
        private int size = 0;

        void offer(String item) {
            if (size == items.length) grow();
            items[(head + size) % items.length] = item;   // the back, wrapping around
            size++;
        }

        String poll() {
            if (size == 0) return null;                   // like Queue.poll on an empty queue
            String front = items[head];
            items[head] = null;
            head = (head + 1) % items.length;
            size--;
            return front;
        }

        private void grow() {
            String[] bigger = new String[items.length * 2];
            for (int i = 0; i < size; i++) bigger[i] = items[(head + i) % items.length];  // queue order
            items = bigger;
            head = 0;
            System.out.println("  grew to capacity " + items.length);
        }

        String state() {
            StringBuilder order = new StringBuilder();
            for (int i = 0; i < size; i++) order.append(items[(head + i) % items.length]).append(i < size - 1 ? " " : "");
            return "raw " + Arrays.toString(items).replace("null", "_") + " head=" + head + " size=" + size + " queue: " + order;
        }
    }

    public static void main(String[] args) {
        CircularQueue q = new CircularQueue();
        for (String job : new String[]{"A", "B", "C", "D"}) q.offer(job);
        System.out.println("offer A B C D -> " + q.state());
        System.out.println("poll " + q.poll() + ", poll " + q.poll() + " -> " + q.state());
        q.offer("E");
        q.offer("F");
        System.out.println("offer E F     -> " + q.state());
        q.offer("G");
        System.out.println("offer G       -> " + q.state());
        StringBuilder rest = new StringBuilder();
        String job;
        while ((job = q.poll()) != null) rest.append(job);
        System.out.println("drain: " + rest + ", then poll -> " + q.poll());
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

public class DequeDemo {
    static List<Integer> windowMax(int[] a, int k) {
        Deque<Integer> dq = new ArrayDeque<>();      // indices, values decreasing
        List<Integer> maxes = new ArrayList<>();
        for (int i = 0; i < a.length; i++) {
            if (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();     // slid out
            while (!dq.isEmpty() && a[dq.peekLast()] <= a[i]) dq.pollLast();  // can never win again
            dq.offerLast(i);
            System.out.println("  i=" + i + " value=" + a[i] + " deque indices=" + dq);
            if (i >= k - 1) maxes.add(a[dq.peekFirst()]);
        }
        return maxes;
    }

    public static void main(String[] args) {
        Deque<String> dq = new ArrayDeque<>();
        dq.offerLast("b");
        dq.offerLast("c");
        dq.offerFirst("a");
        dq.offerLast("d");
        System.out.println("after offers: " + dq);
        System.out.println("pollFirst -> " + dq.pollFirst() + ", pollLast -> " + dq.pollLast() + ", left " + dq);
        System.out.println("peekFirst " + dq.peekFirst() + ", peekLast " + dq.peekLast());

        int[] temps = {9, 3, 1, 4, 2, 6, 5, 1};
        System.out.println("max of each window of 3:");
        System.out.println("result " + windowMax(temps, 3));
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

public class PriorityQueueDemo {
    record Ticket(int severity, int arrival, String title) {}

    public static void main(String[] args) {
        PriorityQueue<Ticket> tickets = new PriorityQueue<>(
                Comparator.comparingInt(Ticket::severity).thenComparingInt(Ticket::arrival));
        String[] titles = {"slow page", "login down", "typo", "payment error", "broken link"};
        int[] severity = {3, 1, 4, 2, 2};
        for (int i = 0; i < titles.length; i++) {
            tickets.offer(new Ticket(severity[i], i, titles[i]));
        }
        System.out.println("next up (peek): " + tickets.peek().title());
        int served = 1;
        while (!tickets.isEmpty()) {
            Ticket t = tickets.poll();
            System.out.println(served++ + ". [sev " + t.severity() + ", #" + t.arrival() + "] " + t.title());
        }

        // Max-heap: reverse the natural order
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Comparator.reverseOrder());
        for (int x : new int[]{15, 3, 42, 8, 23}) maxHeap.offer(x);
        List<Integer> largestFirst = new ArrayList<>();
        while (!maxHeap.isEmpty()) largestFirst.add(maxHeap.poll());
        System.out.println("max-heap poll order: " + largestFirst);

        // The heap array is only partially ordered
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int x : new int[]{5, 3, 2, 7, 4, 1}) minHeap.offer(x);
        System.out.println("raw heap array: " + minHeap);
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class StackApplications {
    static boolean balanced(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if ("([{".indexOf(c) >= 0) stack.push(c);
            else if (")]}".indexOf(c) >= 0) {
                if (stack.isEmpty()) return false;                     // closer with nothing open
                char open = stack.pop();
                if ("([{".indexOf(open) != ")]}".indexOf(c)) return false;   // wrong partner
            }
        }
        return stack.isEmpty();                                         // nothing left open
    }

    static int evalPostfix(String expr) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String token : expr.split(" ")) {
            if (token.matches("-?\\d+")) {
                stack.push(Integer.parseInt(token));
                continue;
            }
            int right = stack.pop(), left = stack.pop();               // right operand comes off first
            stack.push(switch (token) {
                case "+" -> left + right;
                case "-" -> left - right;
                case "*" -> left * right;
                default -> left / right;
            });
        }
        return stack.pop();
    }

    static int[] nextGreater(int[] a) {
        int[] answer = new int[a.length];
        Arrays.fill(answer, -1);
        Deque<Integer> waiting = new ArrayDeque<>();                   // indices, values decreasing
        for (int i = 0; i < a.length; i++) {
            while (!waiting.isEmpty() && a[waiting.peek()] < a[i]) answer[waiting.pop()] = a[i];
            waiting.push(i);
        }
        return answer;
    }

    public static void main(String[] args) {
        for (String s : new String[]{"{[()()]}", "(]", "((", "())"}) {
            System.out.println("balanced(\"" + s + "\") = " + balanced(s));
        }
        System.out.println("5 1 2 + 4 * + 3 - = " + evalPostfix("5 1 2 + 4 * + 3 -"));
        System.out.println("20 4 / 3 - = " + evalPostfix("20 4 / 3 -"));
        int[] prices = {4, 7, 3, 5, 9, 1};
        System.out.println("values:       " + Arrays.toString(prices));
        System.out.println("next greater: " + Arrays.toString(nextGreater(prices)));
    }
}

