import re


def balanced(s):
    stack = []
    for c in s:
        if c in "([{":
            stack.append(c)
        elif c in ")]}":
            if not stack:
                return False  # closer with nothing open
            if "([{".index(stack.pop()) != ")]}".index(c):
                return False  # wrong partner
    return not stack          # nothing left open


def eval_postfix(expr):
    stack = []
    for token in expr.split(" "):
        if re.fullmatch(r"-?\d+", token):
            stack.append(int(token))
            continue
        right, left = stack.pop(), stack.pop()  # right operand comes off first
        if token == "+":
            stack.append(left + right)
        elif token == "-":
            stack.append(left - right)
        elif token == "*":
            stack.append(left * right)
        else:
            stack.append(int(left / right))  # truncate toward zero like Java
    return stack.pop()


def next_greater(a):
    answer = [-1] * len(a)
    waiting = []  # indices, values decreasing
    for i, value in enumerate(a):
        while waiting and a[waiting[-1]] < value:
            answer[waiting.pop()] = value
        waiting.append(i)
    return answer


for s in ["{[()()]}", "(]", "((", "())"]:
    print(f'balanced("{s}") = {str(balanced(s)).lower()}')
print("5 1 2 + 4 * + 3 - =", eval_postfix("5 1 2 + 4 * + 3 -"))
print("20 4 / 3 - =", eval_postfix("20 4 / 3 -"))
prices = [4, 7, 3, 5, 9, 1]
print("values:      ", prices)
print("next greater:", next_greater(prices))

